/// <summary>
/// desigend from AVA
/// </summary>
public void modified()
{
    FormDataObject   formDataObject = any2Object(this) as FormDataObject;
    FormDataSource   formDataSource = formDataObject.datasource();
    FormRun          formRun = formDataSource.formRun();
    ProdParmStartUp  prodParmStartUp = formDataSource.cursor(); ;

    next modified();

    formRun.design().controlName('AVASetupButtonProdProdOrder').enabled(ProdParmStartUp.AVAPrintProdProdOrder);
    formRun.design().controlName('ProdParmStartUp_AVAPrintReference').enabled(prodParmStartUp.AVAPrintProdProdOrder);
    if (prodParmStartUp.AVAPrintProdProdOrder == NoYes::No)
    {
        prodParmStartUp.AVAPrintReference =  NoYes::No;
    }
}
